// wf.legal.tool_search > "Plan": the query the agent wrote, embedded with the model of legal.retrieval (bge-m3 through
// Ollama, as when the knowledge base was embedded).
const s = $('Start').first().json;
const cfg = $input.first().json.cfg || {};
let r = {};
try { r = typeof cfg['legal.retrieval'] === 'string' ? JSON.parse(cfg['legal.retrieval']) : (cfg['legal.retrieval'] || {}); } catch (e) { r = {}; }
const q = String(s.query || '').replace(/\s+/g, ' ').trim().slice(0, 500);
return [{ json: { t0: Date.now(), q, url: `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`,
  body: { model: r.model || 'bge-m3', input: [q], truncate: true, keep_alive: cfg['llm.keep_alive'] || '10m' } } }];

// wf.legal.tool_search > "Search input": embedding answer -> parameters of app.legal_search. Without a vector (the
// embedding call failed) the search is lexical (spec 8.8: degrade, not fail).
const s = $('Start').first().json;
const plan = $('Plan').first().json;
const res = $input.first().json;
let vec = null;
try {
  let b = res.body !== undefined ? res.body : res;
  if (typeof b === 'string') b = JSON.parse(b);
  const v = b && b.embeddings && b.embeddings[0];
  if (Array.isArray(v) && v.length === 1024) vec = `[${v.join(',')}]`;
} catch (e) { vec = null; }
return [{ json: { params: [s.session_id, s.user_id, s.request_id, plan.q, vec, s.jurisdiction || null], embed_ms: Date.now() - plan.t0 } }];

// wf.legal.tool_search > "Tool answer": what the model sees, numbered excerpts with their source.
const r = $input.first().json.r || {};
const ex = r.excerpts || [];
if (!ex.length) return [{ json: { found: 0, note: 'No excerpt found for this query.', excerpts: [] } }];
return [{ json: { found: ex.length, excerpts: ex.map((e) => ({ n: e.n, source: e.source, type: e.type,
  article: e.article || null, text: e.text })) } }];
